## Objective

Build a production-style dependency graph using manual constructor injection in Dart and Flutter.

## Step 1 — Define the Contract

```dart
abstract interface class UserRepository {
  Future<String> fetchUserName();
}
```

The application-facing code depends on this contract rather than a concrete repository implementation.

## Step 2 — Create the Infrastructure Dependency

```dart
class ApiClient {
  Future<String> getUserName() async {
    await Future<void>.delayed(const Duration(milliseconds: 100));
    return 'Flutter Developer';
  }
}
```

## Step 3 — Inject the Infrastructure Dependency

```dart
class RemoteUserRepository implements UserRepository {
  final ApiClient apiClient;

  RemoteUserRepository(this.apiClient);

  @override
  Future<String> fetchUserName() {
    return apiClient.getUserName();
  }
}
```

The repository does not create the API client.

## Step 4 — Inject the Repository

```dart
class UserService {
  final UserRepository repository;

  UserService(this.repository);

  Future<String> loadUserName() {
    return repository.fetchUserName();
  }
}
```

The service depends on the repository contract.

## Step 5 — Inject the Service Into the Controller

```dart
import 'package:flutter/foundation.dart';

class UserController extends ChangeNotifier {
  final UserService service;

  UserController(this.service);

  String? _userName;
  bool _isLoading = false;
  Object? _error;

  String? get userName => _userName;
  bool get isLoading => _isLoading;
  Object? get error => _error;

  Future<void> loadUser() async {
    if (_isLoading) return;

    _isLoading = true;
    _error = null;
    notifyListeners();

    try {
      _userName = await service.loadUserName();
    } catch (error) {
      _error = error;
    } finally {
      _isLoading = false;
      notifyListeners();
    }
  }
}
```

The controller does not create the service or repository.

## Step 6 — Build the Dependency Graph

```dart
final apiClient = ApiClient();
final repository = RemoteUserRepository(apiClient);
final service = UserService(repository);
final controller = UserController(service);
```

The dependency graph is now:

```text
ApiClient
    ↓
RemoteUserRepository
    ↓
UserService
    ↓
UserController
```

## Step 7 — Use the Graph in Flutter

```dart
import 'package:flutter/material.dart';

class UserPage extends StatefulWidget {
  final UserController controller;

  const UserPage({
    super.key,
    required this.controller,
  });

  @override
  State<UserPage> createState() => _UserPageState();
}

class _UserPageState extends State<UserPage> {
  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onControllerChanged);
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onControllerChanged);
    super.dispose();
  }

  void _onControllerChanged() {
    if (mounted) {
      setState(() {});
    }
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Dependency Injection'),
      ),
      body: Center(
        child: controller.isLoading
            ? const CircularProgressIndicator()
            : controller.error != null
                ? Text('Error: ${controller.error}')
                : Text(
                    controller.userName ?? 'Press the button to load user',
                  ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: controller.loadUser,
        child: const Icon(Icons.refresh),
      ),
    );
  }
}
```

## Step 8 — Complete Composition Root

```dart
import 'package:flutter/material.dart';
import 'package:flutter/foundation.dart';

abstract interface class UserRepository {
  Future<String> fetchUserName();
}

class ApiClient {
  Future<String> getUserName() async {
    await Future<void>.delayed(const Duration(milliseconds: 100));
    return 'Flutter Developer';
  }
}

class RemoteUserRepository implements UserRepository {
  final ApiClient apiClient;

  RemoteUserRepository(this.apiClient);

  @override
  Future<String> fetchUserName() {
    return apiClient.getUserName();
  }
}

class UserService {
  final UserRepository repository;

  UserService(this.repository);

  Future<String> loadUserName() {
    return repository.fetchUserName();
  }
}

class UserController extends ChangeNotifier {
  final UserService service;

  UserController(this.service);

  String? _userName;
  bool _isLoading = false;
  Object? _error;

  String? get userName => _userName;
  bool get isLoading => _isLoading;
  Object? get error => _error;

  Future<void> loadUser() async {
    if (_isLoading) return;

    _isLoading = true;
    _error = null;
    notifyListeners();

    try {
      _userName = await service.loadUserName();
    } catch (error) {
      _error = error;
    } finally {
      _isLoading = false;
      notifyListeners();
    }
  }
}

class UserPage extends StatefulWidget {
  final UserController controller;

  const UserPage({
    super.key,
    required this.controller,
  });

  @override
  State<UserPage> createState() => _UserPageState();
}

class _UserPageState extends State<UserPage> {
  @override
  void initState() {
    super.initState();
    widget.controller.addListener(_onControllerChanged);
  }

  @override
  void dispose() {
    widget.controller.removeListener(_onControllerChanged);
    super.dispose();
  }

  void _onControllerChanged() {
    if (mounted) {
      setState(() {});
    }
  }

  @override
  Widget build(BuildContext context) {
    final controller = widget.controller;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Dependency Injection'),
      ),
      body: Center(
        child: controller.isLoading
            ? const CircularProgressIndicator()
            : controller.error != null
                ? Text('Error: ${controller.error}')
                : Text(
                    controller.userName ?? 'Press the button to load user',
                  ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: controller.loadUser,
        child: const Icon(Icons.refresh),
      ),
    );
  }
}

void main() {
  final apiClient = ApiClient();
  final repository = RemoteUserRepository(apiClient);
  final service = UserService(repository);
  final controller = UserController(service);

  runApp(
    MaterialApp(
      debugShowCheckedModeBanner: false,
      home: UserPage(controller: controller),
    ),
  );
}
```

## Testing the Dependency Boundary

A fake implementation can replace the production repository:

```dart
class FakeUserRepository implements UserRepository {
  final String name;

  FakeUserRepository(this.name);

  @override
  Future<String> fetchUserName() async {
    return name;
  }
}
```

Now the same service can be created with the fake:

```dart
final repository = FakeUserRepository('Test User');
final service = UserService(repository);
```

The `UserService` implementation does not change.

This is one of the most important practical benefits of constructor injection.
